CREATE OR REPLACE FUNCTION public.mha_admin_create_company(p_company_code text, p_company_name text)\n RETURNS bigint\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_id bigint;\nbegin\n if auth.uid() is null or not exists(select 1 from public.mha_super_admin_identity sa join public.mha_user_profile u on u.user_id=sa.user_id where sa.user_id=auth.uid() and u.is_active and u.is_super_admin) then raise exception 'Super Admin access required' using errcode='42501';end if;\n if length(trim(coalesce(p_company_code,''))) not between 2 and 30 or trim(coalesce(p_company_code,'')) !~ '^[A-Za-z0-9_-]+$' or length(trim(coalesce(p_company_name,''))) not between 2 and 150 then raise exception 'Invalid company code or name';end if;\n insert into public.mha_company(company_code,company_name) values(upper(trim(p_company_code)),trim(p_company_name)) returning id into v_id;\n return v_id;\nend $function$\n

-- Explicit least-privilege grants are required on a fresh migration replay.
REVOKE ALL ON FUNCTION public.mha_admin_create_company(text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mha_admin_create_company(text,text) TO authenticated;
